import Database from 'better-sqlite3';
import { join } from 'path';

const dbPath = join(process.cwd(), 'rbac.db');
const db = new Database(dbPath);

// Enable foreign keys
db.pragma('foreign_keys = ON');

// Create tables
db.exec(`
  CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    username TEXT UNIQUE NOT NULL,
    password TEXT NOT NULL,
    role TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS content (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    body TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS sessions (
    id TEXT PRIMARY KEY,
    userId INTEGER NOT NULL,
    createdAt INTEGER NOT NULL,
    FOREIGN KEY(userId) REFERENCES users(id) ON DELETE CASCADE
  );
`);

// Seed tables if empty
const userCount = db.prepare('SELECT COUNT(*) as count FROM users').get() as { count: number };
if (userCount.count === 0) {
  const insertUser = db.prepare('INSERT INTO users (username, password, role) VALUES (?, ?, ?)');
  insertUser.run('admin', 'Admin#123', 'admin');
  insertUser.run('editor', 'Editor#123', 'editor');
  insertUser.run('viewer', 'Viewer#123', 'viewer');
}

const contentCount = db.prepare('SELECT COUNT(*) as count FROM content').get() as { count: number };
if (contentCount.count === 0) {
  // Let's use INSERT INTO with explicit ids to ensure they are 1 and 2,
  // and set the auto-increment counter correctly
  const insertContent = db.prepare('INSERT INTO content (id, title, body) VALUES (?, ?, ?)');
  insertContent.run(1, 'Getting Started', 'Welcome to the dashboard');
  insertContent.run(2, 'Company Roadmap', 'Plans for the next quarter');
}

export { db };
export interface User {
  id: number;
  username: string;
  role: string;
}
export interface Session {
  id: string;
  userId: number;
  createdAt: number;
}
export interface Content {
  id: number;
  title: string;
  body: string;
}

import type { RequestHandler } from '@builder.io/qwik-city';
import { db } from '../lib/db';

export const onRequest: RequestHandler = async (event) => {
  const sessionCookie = event.cookie.get('session');
  if (sessionCookie) {
    const sessionId = sessionCookie.value;
    try {
      const sessionData = db.prepare(`
        SELECT s.id as sessionId, u.id as userId, u.username, u.role
        FROM sessions s
        JOIN users u ON s.userId = u.id
        WHERE s.id = ?
      `).get(sessionId) as { sessionId: string; userId: number; username: string; role: string } | undefined;

      if (sessionData) {
        event.sharedMap.set('user', {
          id: sessionData.userId,
          username: sessionData.username,
          role: sessionData.role,
        });
      }
    } catch (err) {
      console.error('Error fetching session in middleware:', err);
    }
  }
  await event.next();
};

import type { RequestHandler } from '@builder.io/qwik-city';
import { db } from '../../../lib/db';
import crypto from 'crypto';

export const onPost: RequestHandler = async (event) => {
  try {
    const body = await event.request.json();
    const { username, password } = body || {};

    if (!username || !password) {
      event.status(401);
      event.json(401, { error: 'Username and password are required' });
      return;
    }

    // Lookup user
    const user = db.prepare('SELECT * FROM users WHERE username = ?').get(username) as any;

    if (!user || user.password !== password) {
      event.status(401);
      event.json(401, { error: 'Invalid credentials' });
      return;
    }

    // Create session
    const sessionId = crypto.randomUUID();
    const createdAt = Date.now();

    db.prepare('INSERT INTO sessions (id, userId, createdAt) VALUES (?, ?, ?)').run(
      sessionId,
      user.id,
      createdAt
    );

    // Set cookie
    event.cookie.set('session', sessionId, {
      httpOnly: true,
      path: '/',
      sameSite: 'lax',
      secure: false, // since we are running locally, secure can be false
    });

    event.status(200);
    event.json(200, {
      username: user.username,
      role: user.role,
    });
  } catch (err) {
    console.error('Login error:', err);
    event.status(401);
    event.json(401, { error: 'Invalid request' });
  }
};

import type { RequestHandler } from '@builder.io/qwik-city';
import { db } from '../../../lib/db';

export const onPost: RequestHandler = async (event) => {
  const sessionCookie = event.cookie.get('session');
  if (sessionCookie) {
    const sessionId = sessionCookie.value;
    try {
      db.prepare('DELETE FROM sessions WHERE id = ?').run(sessionId);
    } catch (err) {
      console.error('Logout db error:', err);
    }
  }

  // Clear cookie
  event.cookie.delete('session', { path: '/' });

  event.status(200);
  event.json(200, { message: 'Logged out successfully' });
};

import type { RequestHandler } from '@builder.io/qwik-city';
import { db } from '../../../lib/db';

export const onGet: RequestHandler = async (event) => {
  const user = event.sharedMap.get('user');
  if (!user) {
    event.status(401);
    event.json(401, { error: 'Unauthorized' });
    return;
  }

  try {
    const contentList = db.prepare('SELECT id, title, body FROM content ORDER BY id ASC').all();
    event.status(200);
    event.json(200, contentList);
  } catch (err) {
    console.error('Fetch content error:', err);
    event.status(500);
    event.json(500, { error: 'Internal Server Error' });
  }
};

export const onPost: RequestHandler = async (event) => {
  const user = event.sharedMap.get('user');
  if (!user) {
    event.status(401);
    event.json(401, { error: 'Unauthorized' });
    return;
  }

  if (user.role !== 'admin' && user.role !== 'editor') {
    event.status(403);
    event.json(403, { error: 'Forbidden' });
    return;
  }

  try {
    const body = await event.request.json();
    const { title, body: contentBody } = body || {};

    if (!title || !contentBody) {
      event.status(400);
      event.json(400, { error: 'Title and body are required' });
      return;
    }

    // Insert new content. Note: Server assigns id, ignore any client-supplied id.
    const result = db.prepare('INSERT INTO content (title, body) VALUES (?, ?)').run(title, contentBody);
    const newId = result.lastInsertRowid;

    event.status(201);
    event.json(201, {
      id: Number(newId),
      title,
      body: contentBody,
    });
  } catch (err) {
    console.error('Create content error:', err);
    event.status(400);
    event.json(400, { error: 'Invalid request' });
  }
};

import type { RequestHandler } from '@builder.io/qwik-city';
import { db } from '../../../../lib/db';

export const onDelete: RequestHandler = async (event) => {
  const user = event.sharedMap.get('user');
  if (!user) {
    event.status(401);
    event.json(401, { error: 'Unauthorized' });
    return;
  }

  if (user.role !== 'admin' && user.role !== 'editor') {
    event.status(403);
    event.json(403, { error: 'Forbidden' });
    return;
  }

  const idStr = event.params.id;
  const id = parseInt(idStr, 10);
  if (isNaN(id)) {
    event.status(400);
    event.json(400, { error: 'Invalid ID' });
    return;
  }

  try {
    // Check if it exists
    const content = db.prepare('SELECT id FROM content WHERE id = ?').get(id);
    if (!content) {
      event.status(404);
      event.json(404, { error: 'Content not found' });
      return;
    }

    // Delete
    db.prepare('DELETE FROM content WHERE id = ?').run(id);

    event.status(200);
    event.json(200, { message: 'Content deleted successfully' });
  } catch (err) {
    console.error('Delete content error:', err);
    event.status(500);
    event.json(500, { error: 'Internal Server Error' });
  }
};

